async function readWind(day, env, options=modelOptions(new URLSearchParams())) {
  if(!env.KNMI_EDR_API_KEY)throw Error('KNMI_NOT_CONFIGURED');
  const cacheKey=day+JSON.stringify(options);
  const hit=windCache.get(cacheKey);if(hit&&Date.now()<hit.expires)return hit.promise;
  const promise=(async()=>{
    // The UTC interval includes both possible Dutch day boundaries, including DST.
    const base=Date.parse(day+'T00:00:00Z');
    const query=new URLSearchParams({'datetime':`${new Date(base-3*3600000).toISOString()}/${new Date(base+25*3600000).toISOString()}`,'parameter-name':'ff'});
    const controller=new AbortController();
    const timer=setTimeout(()=>controller.abort(),20000);
    let r;
    try { r=await fetch('https://api.dataplatform.knmi.nl/edr/v1/collections/10-minute-in-situ-meteorological-observations/locations/'+options.stationId+'?'+query,{headers:{Authorization:env.KNMI_EDR_API_KEY.trim(),Accept:'application/json'},redirect:'manual',signal:controller.signal}); } catch(e) { console.error('KNMI_FETCH_FAILED',e?.name||'Error');throw Error('KNMI_CONNECTION'); } finally {clearTimeout(timer);}
    if(!r.ok){console.error('KNMI_HTTP_STATUS',r.status);throw Error(r.status===401||r.status===403?'KNMI_AUTH':'KNMI_UNAVAILABLE');}
    const profile=modelHours(await r.json(),day,options,true);
    return {day,station:options.stationName,...profile};
  })();
  windCache.set(cacheKey,{promise,expires:Date.now()+300000});promise.catch(()=>windCache.delete(cacheKey));
  if(windCache.size>100)windCache.delete(windCache.keys().next().value);
  return promise;
}

function stationsByDistance(park) {
  // Approximate park centres; great-circle distance in kilometres.
  const centre=park==='beabuorren'?[53.052,5.493]:[53.017,5.367];
  const rad=v=>v*Math.PI/180;
  return stationCatalog.map(s=>{const a=Math.sin(rad(s.latitude-centre[0])/2)**2+Math.cos(rad(centre[0]))*Math.cos(rad(s.latitude))*Math.sin(rad(s.longitude-centre[1])/2)**2;return {...s,distanceKM:6371*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a))};}).sort((a,b)=>a.distanceKM-b.distanceKM||a.name.localeCompare(b.name));
}

// A source interval represents a ten-minute mean, not instantaneous power.
function runtimeStats(intervals, thresholdMW, share=1) {
  if(!Number.isFinite(thresholdMW)||thresholdMW<=0||!Number.isFinite(share)||share<=0||share>1)return null;
  let total=0,longest=0,run=0,lastEnd=null;
  for(const interval of intervals){
    const start=Date.parse(interval.start),end=Date.parse(interval.end);
    const valid=Number.isFinite(start)&&end-start===600000&&typeof interval.powerMW==='number'&&Number.isFinite(interval.powerMW);
    if(!valid||interval.powerMW*share<thresholdMW){run=0;lastEnd=null;continue;}
    run=lastEnd===start?run+10:10;total+=10;longest=Math.max(longest,run);lastEnd=end;
  }
  return {totalMinutes:total,longestMinutes:longest};
}

function combinedSupply(fryslan, beabuorren) {
  const a=new Map(fryslan.map(i=>[i.start,i])),b=new Map(beabuorren.map(i=>[i.start,i]));
  return [...new Set([...a.keys(),...b.keys()])].sort().map(start=>{
    const x=a.get(start),y=b.get(start);
    const valid=x&&y&&x.end===y.end&&typeof x.powerMW==='number'&&Number.isFinite(x.powerMW)&&typeof y.powerMW==='number'&&Number.isFinite(y.powerMW);
    return {start,end:x?.end||y.end,powerMW:valid?(x.powerMW*.1+y.powerMW)/1.1:null};
  });
}

// Group near-equal model outputs instead of treating each decimal as a new value.
function mostFrequentPower(intervals) {
  const buckets=new Map();let availableMinutes=0;
  for(const i of intervals){
    const v=i.powerMW,start=Date.parse(i.start),end=Date.parse(i.end);
    if(typeof v!=='number'||!Number.isFinite(v)||v<0||end-start!==600000)continue;
    const band=Math.floor(v);buckets.set(band,(buckets.get(band)||0)+10);availableMinutes+=10;
  }
  if(!buckets.size)return null;
  const [lowerMW,minutes]=[...buckets].sort((a,b)=>b[1]-a[1]||a[0]-b[0])[0];
  const tiedBands=[...buckets].filter(([,n])=>n===minutes).length;
  return {lowerMW,upperMW:lowerMW+1,lineMW:lowerMW+.5,minutes,availableMinutes,tiedBands};
}

function researchResults(intervals) {
  const valid=intervals.filter(i=>typeof i.powerMW==='number'&&Number.isFinite(i.powerMW)&&Date.parse(i.end)-Date.parse(i.start)===600000);
  if(!valid.length)return null;
  const availableHours=valid.length/6;
  const descending=valid.map(i=>i.powerMW).sort((a,b)=>b-a);
  const reliable=fraction=>descending[Math.max(0,Math.ceil(descending.length*fraction)-1)];
  const sizes=[1,2,3,4,5,7.5,10,12.5,15,17.5,20,22.5,25,27.5,30,32.5,35,37.5,40,42.5,44,44.25];
  const rows=sizes.map(capacityMW=>{
    const energyMWh=valid.reduce((sum,i)=>sum+Math.min(capacityMW,Math.max(0,i.powerMW))/6,0);
    const stats=runtimeStats(intervals,capacityMW);
    return {capacityMW,energyMWh,equivalentFullLoadHours:energyMWh/capacityMW,utilisation:energyMWh/(capacityMW*availableHours),fullLoadHours:stats.totalMinutes/60,longestHours:stats.longestMinutes/60};
  });
  return {availableHours,power90:reliable(.9),power50:reliable(.5),rows};
}

